t_id\') AS STRING) AS product_id, CAST(JSON_EXTRACT_SCALAR(PARSE_JSON(line_item), \'$.name\') AS STRING) AS product_name, CAST(JSON_EXTRACT_SCALAR(PARSE_JSON(line_item), \'$.parent_name\') AS STRING) AS product_parent_name, currency, status AS order_status, REPLACE(IF(ARRAY_LENGTH(refunds) > 0, JSON_EXTRACT_SCALAR(PARSE_JSON(refunds[OFFSET(0)]), \'$.id\'), NULL), \'\"\', \'\') AS refunds_id, CAST(date_created_gmt AS TIMESTAMP) AS order_timestamp, SAFE_CAST(JSON_EXTRACT_SCALAR(PARSE_JSON(line_item), \'$.total\') AS FLOAT64) + SAFE_CAST(JSON_EXTRACT_SCALAR(PARSE_JSON(line_item), \'$.total_tax\') AS FLOAT64) AS line_item_sales, SAFE_CAST(shipping_total AS FLOAT64) / COUNT(DISTINCT JSON_EXTRACT_SCALAR(PARSE_JSON(line_item), \'$.id\')) OVER (PARTITION BY id) AS shipping_price, SAFE_CAST(shipping_tax AS FLOAT64) / COUNT(DISTINCT JSON_EXTRACT_SCALAR(PARSE_JSON(line_item), \'$.id\')) OVER (PARTITION BY id) AS shipping_tax, SAFE_CAST(JSON_EXTRACT_SCALAR(PARSE_JSON(line_item), \'$.quantity\') AS FLOAT64) AS quantity, \'WooCommerce\' AS source, payment_method FROM `samandmarshall-wh.maplemonk.woocommerce_SamAndMarshall_All_orders`, UNNEST(line_items) AS line_item ) SELECT CTE.*, pa.grip, pa.size, pa.color_general, pa.color_specific, pa.product_brand, pa.gender, pa.attribute_1, pa.attribute_2, pa.attribute_3, pa.supplier, pa.model, pa.type, pa.product_short_name1, pa.product_short_name2, pa.category1, pa.category2, pa.category3, pa.category4, pa.category5, IFNULL(d.discount_allocations, 0) AS discount, CTE.line_item_sales AS gross_sales_after_tax, CTE.line_item_sales - IFNULL(SAFE_CAST(t.tax_lines AS FLOAT64), 0) AS gross_sales_before_tax, CTE.line_item_sales - IFNULL(SAFE_CAST(t.tax_lines AS FLOAT64), 0) - IFNULL(d.discount_allocations, 0) AS net_sales_before_tax, IFNULL(SAFE_CAST(t.tax_lines AS FLOAT64), 0) AS tax, CTE.line_item_sales + IFNULL(shipping_price, 0) + IFNULL(shipping_tax, 0) AS total_sales, FROM CTE LEFT JOIN `samandmarshall-wh.maplemonk.woocommerce_SamAndMarshall_All_orders_items_tax` t ON CTE.order_id = CAST(t.order_id AS STRING) AND CTE.line_item_id = t.line_item_id AND CTE.shop_name = t.shop_name LEFT JOIN `samandmarshall-wh.maplemonk.woocommerce_SamAndMarshall_All_orders_items_discount` d ON CTE.order_id = CAST(d.order_id AS STRING) AND CTE.line_item_id = d.line_item_id AND CTE.shop_name = d.shop_name LEFT JOIN `samandmarshall-wh.maplemonk.woocommerce_all_orders_products_attributes` pa ON CTE.order_id = CAST(pa.order_id AS STRING) AND CTE.product_id = CAST(pa.product_id AS STRING) AND CTE.shop_name = pa.shop_name AND CTE.sku = pa.sku AND CTE.line_item_id = pa.line_item_id; CREATE OR REPLACE TABLE samandmarshall-wh.maplemonk.FACT_ITEMS_woocommerce_SamAndMarshall AS SELECT o.shop_name, o.order_id, o.order_name, o.customer_id, o.name, o.email, o.phone, o.line_item_id, o.sku, o.product_id, o.product_name, o.currency, o.city, o.state, o.country, o.grip, o.product_brand, o.size, o.color_general, o.color_specific, o.attribute_1, o.attribute_2, o.attribute_3, o.model, o.type, o.supplier, o.gender, o.product_short_name1, o.product_short_name2, CASE WHEN LOWER(o.product_name) LIKE \'%bling%\' THEN \'Bling\' WHEN LOWER(o.product_name) LIKE \'%classic%\' THEN \'Classic\' END AS print, o.category1, o.category2, o.category3, o.category4, o.category5, o.order_status, o.order_timestamp, o.line_item_sales, o.shipping_price, o.quantity, o.tax, o.discount, o.gross_sales_after_tax, o.gross_sales_before_tax, o.net_sales_before_tax, o.total_sales, o.payment_method, CAST(NULL AS STRING) AS new_customer_flag, CAST(NULL AS STRING) AS new_customer_flag_month, CAST(NULL AS STRING) AS acquisition_channel, CAST(NULL AS STRING) AS acquisition_product, CAST(NULL AS STRING) as warehouse_name, CAST(NULL AS STRING) as shipping_status, CAST(NULL AS STRING) AS reference_code ,CAST(NULL AS STRING) AS SHIPPING_LAST_UPDATE_DATE ,CAST(NULL AS STRING) AS FINAL_SHIPPING_STATUS ,CAST(line_item_id AS STRING) AS SALEORDERITEMCODE ,CAST(NULL AS STRING) AS AWB ,CAST(NULL AS STRING) AS payment_gateway ,CAST(NULL AS STRING) AS COURIER ,CAST(NULL AS datetime) AS DISPATCH_DATE ,CAST(NULL AS datetime) AS delivered_date ,CAST(NULL AS STRING) AS DELIVERED_STATUS ,case when lower(order_status) = \'refunded\' then 1 else 0 end as return_flag ,case when lower(order_status) = \'refunded\'then o.quantity else 0 end AS returned_quantity ,case when lower(order_status) = \'refunded\'then o.line_item_sales else 0 end AS returned_sales ,case when lower(order_status) in (\'cancelled\') then cast(quantity as int64) end cancelled_quantity ,case when lower(order_status) in (\'cancelled\') then total_sales end as cancel_sales ,CAST(NULL AS STRING) AS days_in_shipment ,CAST(NULL AS datetime) AS ACQUISITION_DATE ,CAST(NULL AS STRING) AS PRODUCT_CATEGORY ,CAST(NULL AS STRING) AS PRODUCT_SUB_CATEGORY ,CAST(NULL AS STRING) AS commonsku ,CAST(NULL AS STRING) AS warehouse ,CAST(NULL AS STRING) AS pincode ,CAST(NULL AS STRING) AS source_pincode ,CAST(NULL AS STRING) AS discount_codes FROM `samandmarshall-wh.maplemonk.woocommerce_SamAndMarshall_All_orders_items` o; UPDATE `samandmarshall-wh.maplemonk.FACT_ITEMS_woocommerce_SamAndMarshall` AS a SET a.new_customer_flag = b.flag FROM ( SELECT order_id, customer_id, CASE WHEN order_timestamp <> MIN(order_timestamp) OVER (PARTITION BY customer_id) THEN \'Repeat\' ELSE \'New\' END AS flag, ROW_NUMBER() OVER (PARTITION BY order_id, customer_id ORDER BY order_timestamp) AS rn FROM `samandmarshall-wh.maplemonk.FACT_ITEMS_woocommerce_SamAndMarshall` ) AS b WHERE a.order_id = b.order_id AND a.customer_id = b.customer_id AND b.rn = 1; UPDATE `samandmarshall-wh.maplemonk.FACT_ITEMS_woocommerce_SamAndMarshall` SET new_customer_flag = COALESCE(new_customer_flag, \'New\') WHERE new_customer_flag IS NULL; UPDATE `samandmarshall-wh.maplemonk.FACT_ITEMS_woocommerce_SamAndMarshall` AS a SET a.new_customer_flag_month = b.flag FROM ( SELECT order_id, customer_id, CASE WHEN LAST_DAY(CAST(order_timestamp AS DATE), MONTH) <> LAST_DAY(CAST(MIN(order_timestamp) OVER (PARTITION BY customer_id) AS DATE), MONTH) THEN \'Repeated\' ELSE \'New\' END AS flag, ROW_NUMBER() OVER (PARTITION BY order_id, customer_id ORDER BY order_timestamp) AS rn FROM `samandmarshall-wh.maplemonk.FACT_ITEMS_woocommerce_SamAndMarshall` ) AS b WHERE a.order_id = b.order_id AND a.customer_id = b.customer_id AND b.rn = 1; CREATE or replace TABLE samandmarshall-wh.maplemonk.temp_product AS SELECT DISTINCT customer_id, product_name, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY line_item_sales DESC) AS rowid FROM ( SELECT DISTINCT customer_id, order_timestamp, product_name, line_item_sales, MIN(order_timestamp) OVER (PARTITION BY customer_id) AS first_order_date FROM `samandmarshall-wh.maplemonk.FACT_ITEMS_woocommerce_SamAndMarshall` ) res WHERE order_timestamp = first_order_date; UPDATE `samandmarshall-wh.maplemonk.FACT_ITEMS_woocommerce_SamAndMarshall` AS a SET a.acquisition_product = b.product_name FROM ( SELECT * FROM samandmarshall-wh.maplemonk.temp_product WHERE rowid = 1 ) AS b WHERE a.customer_id = b.customer_id;",
